findings.codeql_raw_query:
/**
 * @name Directory traversal via mkdir with parents=True
 * @description Creating directories with parents=True on untrusted paths may allow directory traversal
 * @kind path-problem
 * @problem.severity high
 * @id py/filelock-directory-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module DirTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getReturn().getMember("mkdir").getACall() and
      sink = call.getArg(0).getALocalSource()
    )
  }
}

module DirTraversalFlow = TaintTracking::Global<DirTraversalConfig>;
import DirTraversalFlow::PathGraph

from DirTraversalFlow::PathNode source, DirTraversalFlow::PathNode sink
where DirTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Directory creation with untrusted path from $@.", source.getNode(), "parameter"
